<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {get,request} from '../api/client'
type Row=Record<string,any>
const rows=ref<Row[]>([]),detail=ref<Row|null>(null),busy=ref(false),error=ref(''),dialog=ref(false),file=ref<File|null>(null),selected=ref<Row|null>(null)
const form=ref({name:'',description:'',note:'',enabled:true,expectedVersion:0})
let uploadKey=''
function choose(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null;uploadKey=crypto.randomUUID().replaceAll('-','')}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function load(){rows.value=await get('/api/v1/admin/file-library')}
async function inspect(row:Row){detail.value=await get('/api/v1/admin/file-library/'+row.id)}
function edit(row:Row|null){selected.value=row;file.value=null;uploadKey=crypto.randomUUID().replaceAll('-','');form.value={name:row?.name||'',description:row?.description||'',note:'',enabled:row?.enabled??true,expectedVersion:row?.lockVersion||0};dialog.value=true}
async function save(){await act(async()=>{let path='/api/v1/admin/file-library'+(selected.value?'/'+selected.value.id:'');if(file.value){const data=new FormData();data.append('file',file.value);for(const key of ['name','description','note','expectedVersion'] as const)data.append(key,String(form.value[key]));await request('POST',path+(selected.value?'/versions':''),data,uploadKey)}else{if(!selected.value)throw new Error('请选择文件');await request('PUT',path,form.value)}dialog.value=false;await load();if(detail.value)await inspect(detail.value)})}
async function remove(row:Row){if(!confirm('确认删除？已被活动引用的文件需要先解除引用。历史版本保留用于审计。'))return;await act(async()=>{await request('DELETE','/api/v1/admin/file-library/'+row.id+'?expectedVersion='+row.lockVersion);detail.value=null;await load()})}
onMounted(()=>act(load))
</script>
<template><section><div class="title-row"><div><h1>全局文件库</h1><p class="muted">文件传一次，多活动引用。上传新版本保留历史；活动可选择是否开放历史版本。</p></div><button :disabled="busy" @click="edit(null)">上传新文件</button></div><p class="error" role="alert">{{ error }}</p><div class="panel scroll"><table><thead><tr><th>名称</th><th>当前版本</th><th>状态</th><th>活动数</th><th>下载次数</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{ r.name }}</td><td>{{ r.currentVersion }}</td><td>{{ r.enabled?'启用':'停用' }}</td><td>{{ r.activityCount }}</td><td>{{ r.downloadCount }}</td><td><div class="actions"><button class="quiet" @click="act(()=>inspect(r))">版本与引用</button><button class="quiet" @click="edit(r)">编辑 / 新版本</button><button class="danger" @click="remove(r)">删除</button></div></td></tr></tbody></table><p v-if="!rows.length" class="empty">尚无文件，请由运营上传。</p></div><div v-if="detail" class="panel"><h2>{{ detail.name }}</h2><p>{{ detail.description }}</p><h3>版本记录</h3><p v-for="v in detail.versions" :key="v.versionNo">v{{ v.versionNo }} · {{ v.displayName }} · {{ v.sizeBytes }} 字节 · {{ v.note }} · {{ v.createdAt }}</p><h3>引用活动</h3><p v-for="a in detail.activities" :key="a.id"><router-link :to="'/activities/'+a.id">{{ a.title }}</router-link></p><p v-if="!detail.activities.length">暂无引用</p></div><div v-if="dialog" class="overlay"><form class="dialog" @submit.prevent="save"><h2>{{ selected?'编辑文件 / 上传新版本':'上传文件' }}</h2><label>名称<input v-model="form.name" required maxlength="150"/></label><label>说明<textarea v-model="form.description" maxlength="2000"/></label><label>{{ selected?'新版本文件（留空只改名称说明和启用状态）':'文件' }}<input type="file" :required="!selected" accept=".pdf,.png,.jpg,.jpeg,.txt,.zip" @change="choose"/></label><label v-if="file">版本备注<input v-model="form.note" maxlength="500"/></label><label v-if="selected&&!file"><input v-model="form.enabled" type="checkbox"/>启用下载</label><p class="muted">最大10MB。文本须为 UTF-8；扩展名和内容类型由服务器共同校验。</p><p class="error" role="alert">{{ error }}</p><div class="actions"><button :disabled="busy">保存</button><button type="button" class="quiet" :disabled="busy" @click="dialog=false">取消</button></div></form></div></section></template>
